def cli(ctx):
    """Check the latest Apio version."""
    import requests
    import semver
    from apio.core.utils import get_version
    from apio.core.config import get_config

    config = get_config()
    version = get_version()
    latest_version = requests.get(
        'https://pypi.python.org/pypi/apio/json'
    ).json()['info']['version']

    if semver.compare(version, latest_version) == -1:
        ctx.log(
            'A new version of Apio is available: {}'.format(latest_version)
        )
        ctx.log(
            'You are currently using: {}'.format(version)
        )
        ctx.log(
            'You can update Apio by running: {}'.format(
                config.get('update_command')
            )
        )
    else:
        ctx.log(
            'You are using the latest version of Apio: {}'.format(version)
        )

